from marshmallow import Schema, INCLUDE, fields

def test_unknown_include_dotted_keys():
    class MySchema(Schema):
        class Meta:
            unknown = INCLUDE

    s = MySchema()
    res = s.load({"01.12.2019": 1, "01.01.2020": 0})
    assert res == {"01.12.2019": 1, "01.01.2020": 0}

